window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0927f41a7157ca0e"]={"versions": [{"id": "FIG-0927f41a7157ca0e", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Metamodell-Ausschnitt / Klassendiagramm aus dem AUTOSAR System Template (<code>AUTOSAR_TPS_SystemTemplate</code>, Release R22-11).\n</li><li><strong>Architektur-Kontext:</strong> Definiert das formale System-Description-Metamodell zur Abbildung von Layer-2-Sicherheit nach <strong>IEEE 802.1AE (MACsec)</strong> und <strong>IEEE 802.1X (MKA – MACsec Key Agreement Protocol)</strong> für Ethernet-Netzwerktopologien.\n</li><li><strong>Funktionaler Zweck:</strong> Modellierung der statischen Bindeglieder zwischen physischen/logischen Ethernet-Ports (<code>CouplingPort</code>, <code>EthernetCommunicationController</code>), den MKA-Teilnehmerrollen (<code>MacSecKayParticipant</code>), Kryptoschlüsseln (<code>CryptoServiceKey</code>) sowie Security-Parametern (Cipher-Suites, Replay-Schutz, Vertraulichkeits-Offsets). Dient als Eingangsbeschreibung zur Codegenerierung für die AUTOSAR-BSW (u. a. <code>Eth</code>, <code>EthSwt</code>, <code>EthIf</code>, <code>MacSec</code> bzw. MKA-Daemon sowie den AUTOSAR <code>Crypto Stack</code>).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Vererbungshierarchien &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><code>CouplingElement</code> → spezialisiert <code>FibexElement</code>\n</li><li><code>EthernetCommunicationController</code> → spezialisiert <code>CommunicationController</code>\n</li><li><code>CouplingPort</code>, <code>MacSecKayParticipant</code> → spezialisieren <code>Identifiable</code>\n</li><li><code>MacSecGlobalKayProps</code>, <code>MacSecParticipantSet</code>, <code>CryptoServiceKey</code> → spezialisieren <code>ARElement</code>\n</li><li><code>EthernetCluster</code> → spezialisiert <code>CommunicationCluster</code>\n</li></ul>\n<h5 class=\"fig-section-h5\">Topologie- &amp; Port-Entitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>CouplingElement</code>:</strong> Repräsentiert Layer-2-Koppelelemente (z. B. Ethernet-Switches). Komponiert <code>couplingPort [0..*]</code> über die Komposition <code>«atpVariation, atpSplitable»</code>.\n</li><li><strong><code>EthernetCommunicationController</code>:</strong> ECU-Ethernet-Controller mit Parametern für MAC-Unicast-Adresse, Puffergrenzen und Slave-Verhalten; referenziert <code>couplingPort [0..*]</code>.\n</li><li><strong><code>CouplingPort</code>:</strong> Physischer oder logischer Switch-/Controller-Port. Definiert Verhandlungsverhalten, Port-Rollen und Layer-Typen. Komponiert <code>macSecProps [0..*]</code>.\n</li><li><strong><code>EthernetCluster</code>:</strong> Kommunikationscluster für Ethernet-Netzwerke; parametriert <code>couplingPortStartupActiveTime</code> und <code>couplingPortSwitchoffDelay</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">MACsec- &amp; MKA-Konfigurationsentitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>MacSecProps</code>:</strong> Laufzeit- und Betriebsmodi des MACsec-Layers auf Port-Ebene:\n<ul class=\"fig-list\"><li><code>autoStart: Boolean [0..1]</code>: Automatisches Aktivieren der MACsec-Verarbeitung nach Link-Up.\n</li><li><code>onFailPermissiveMode: MacSecFailPermissiveModeEnum [0..1]</code> (<code>never</code>, <code>timeout</code>): Verhalten bei MKA-Verhandlungsfehlschlag (Plaintext-Fallback).\n</li><li><code>onFailPermissiveModeTimeout: TimeValue [0..1]</code>: Gültigkeitsdauer des Permissive-Modes.\n</li><li><code>sakRekeyTimeSpan: TimeValue [0..1]</code>: Intervall für periodisches Rekeying des Security Association Key (SAK).\n</li><li>Komposition <code>macSecKayConfig [0..1]</code> → <code>MacSecLocalKayProps</code>.\n</li></ul>\n</li><li><strong><code>MacSecLocalKayProps</code>:</strong> Lokale MKA/KAY-Eigenschaften der Schnittstelle:\n<ul class=\"fig-list\"><li><code>role: MacSecRoleEnum [0..1]</code> (<code>peer</code>, <code>keyServer</code>): Lokale MKA-Rolle.\n</li><li><code>keyServerPriority: PositiveInteger [0..1]</code>: Priorität bei der dynamischen Key-Server-Wahl.\n</li><li><code>sourceMacAddress</code>, <code>destinationMacAddress</code>: L2-Adressierung der MKA-Nachbarn.\n</li><li>Referenziert <code>globalKayProps [0..1]</code> → <code>MacSecGlobalKayProps</code>.\n</li><li>Referenziert <code>mkaParticipant [0..*]</code> → <code>MacSecKayParticipant</code>.\n</li></ul>\n</li><li><strong><code>MacSecGlobalKayProps</code>:</strong> Globale Whitelist- und Bypass-Regeln:\n<ul class=\"fig-list\"><li><code>bypassEtherType: PositiveInteger [0..255]</code>: EtherTypes, die unverschlüsselt/unauthentifiziert passieren (z. B. PTP/IEEE 802.1AS, LLDP).\n</li><li><code>bypassVlan: PositiveInteger [0..255]</code>: VLAN-IDs für MACsec-Bypass.\n</li></ul>\n</li><li><strong><code>MacSecParticipantSet</code>:</strong> Bündelt <code>mkaParticipant [0..*]</code> und referenziert das übergeordnete <code>ethernetCluster [0..1]</code>.\n</li><li><strong><code>MacSecKayParticipant</code>:</strong> Repräsentiert einen konkreten Teilnehmer an einer Connectivity Association (CA):\n<ul class=\"fig-list\"><li>Referenziert <code>ckn [0..1]</code> → <code>CryptoServiceKey</code>: Connectivity Association Key Name (CKN / Master Pre-Shared Key Identifier).\n</li><li>Referenziert <code>sak [0..1]</code> → <code>CryptoServiceKey</code>: Security Association Key (SAK; aktiver Session-Schlüssel).\n</li><li>Komponiert <code>cryptoAlgoConfig [0..1]</code> → <code>MacSecCryptoAlgoConfig</code>.\n</li></ul>\n</li><li><strong><code>CryptoServiceKey</code>:</strong> AUTOSAR-Kryptoschlüssel-Deklaration mit <code>algorithmFamily</code>, <code>keyGeneration</code>, <code>keyStorageType</code> und <code>length</code>.\n</li><li><strong><code>MacSecCryptoAlgoConfig</code>:</strong> Kryptografische Betriebsbedingungen:\n<ul class=\"fig-list\"><li><code>capability: MacSecCapabilityEnum [0..1]</code> (<code>intergrityWithoutConfidentiality</code>, <code>intergrityAndConfidentiality</code>).\n</li><li><code>confidentialityOffset: MacSecConfidentialityOffsetEnum [0..1]</code> (<code>ConfidentialityOffset_0</code>, <code>ConfidentialityOffset_30</code>, <code>ConfidentialityOffset_50</code>).\n</li><li><code>replayProtection: Boolean [0..1]</code> und <code>replayProtectionWindow: PositiveInteger [0..1]</code>.\n</li><li>Komponiert <code>cipherSuiteConfig [0..4]</code> → <code>MacSecCipherSuiteConfig</code>.\n</li></ul>\n</li><li><strong><code>MacSecCipherSuiteConfig</code>:</strong> Priorisierte Cipher-Suiten (z. B. GCM-AES-128, GCM-AES-256) über <code>cipherSuite: String [0..1]</code> und <code>cipherSuitePriority: PositiveInteger [0..1]</code>.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (MKA / MACsec)</h4>\n<p class=\"fig-p\">Aus den Parametern leitet sich folgende protokollarische Zustands- und Ablaufkette ab:</p>\n<ol class=\"fig-list\"><li><strong>Initialisierung &amp; Link-Up:</strong>\n<ul class=\"fig-list\"><li>Detektiert der Ethernet-Treiber den Link-Up und ist <code>autoStart == true</code>, wird der MKA-Protokollstack (Control Plane) auf dem jeweiligen <code>CouplingPort</code> getriggert.\n</li></ul>\n</li><li><strong>Peer Discovery &amp; Key-Server-Wahl:</strong>\n<ul class=\"fig-list\"><li>MKA sendet EAPOL-MKA-PDUs an <code>destinationMacAddress</code>.\n</li><li>Bei Peer-to-Peer-Beziehungen werten die Teilnehmer <code>keyServerPriority</code> und MAC-Adressen aus; der Teilnehmer mit dem kleinsten Prioritätswert (höchste Präferenz) wird zum <code>keyServer</code>.\n</li></ul>\n</li><li><strong>Authentifizierung &amp; Key Distribution:</strong>\n<ul class=\"fig-list\"><li>Die Authentifizierung erfolgt über den vorab konfigurierten <code>ckn</code> (Connectivity Association Key Name).\n</li><li>Der Key-Server erzeugt den Security Association Key (<code>sak</code>) und verteilt diesen verschlüsselt an die Teilnehmer.\n</li></ul>\n</li><li><strong>Data Plane Enforcement (SecY-Konfiguration):</strong>\n<ul class=\"fig-list\"><li>Der abgeleitete SAK wird in die MACsec-Hardware-Engine (SecY) geladen.\n</li><li>Die Hardware wendet <code>capability</code> (nur ICV-Authentifizierung oder Authentifizierung + Verschlüsselung) sowie <code>replayProtectionWindow</code> an.\n</li><li>Bei Paketen mit passendem <code>bypassEtherType</code> oder <code>bypassVlan</code> wird der SecY-Kryptopfad umgangen.\n</li></ul>\n</li><li><strong>Rekeying &amp; Fehlerabfall:</strong>\n<ul class=\"fig-list\"><li>Vor Ablauf von <code>sakRekeyTimeSpan</code> rolliert der Key-Server automatisch einen neuen SAK ein (Zero-Packet-Loss Rekeying).\n</li><li>Schlägt die MKA-Aushandlung fehl oder bricht der Session-Status ab:\n<ul class=\"fig-list\"><li><code>onFailPermissiveMode == never</code>: Der Port verwirft sofort allen nicht-konformen Plaintext-Verkehr (Fail-Secure).\n</li><li><code>onFailPermissiveMode == timeout</code>: Unverschlüsselter Datenverkehr wird für die Dauer von <code>onFailPermissiveModeTimeout</code> temporär toleriert, bevor der Datenpfad geschlossen wird.\n</li></ul>\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Hardware-Offloading (SecY):</strong> MACsec IEEE 802.1AE erfordert Line-Rate-Kryptografie. Die Konfigurationen aus <code>MacSecCryptoAlgoConfig</code> zielen direkt auf integrierte Hardware-Crypto-Engines in Switch-ICs oder Ethernet-MACs ab. Fehlt dem Controller die HW-Unterstützung, droht immenser MCU-Overhead oder Frame-Dropping.\n</li><li><strong>Header-Transparenz via <code>confidentialityOffset</code>:</strong>\n<ul class=\"fig-list\"><li><code>ConfidentialityOffset_0</code>: Verschlüsselung ab Beginn der Nutzlast (hinter SecTAG).\n</li><li><code>ConfidentialityOffset_30</code> / <code>ConfidentialityOffset_50</code>: Erlaubt das Belassen unverschlüsselter L3/L4-Header (IPv4 bzw. IPv6 / TCP/UDP). Dies ist zwingend erforderlich, wenn Zwischenknoten (z. B. Switched Gateways) Paketinspektion, Routing oder QoS-Klassifizierung ohne vollständige MACsec-Terminierung durchführen müssen.\n</li></ul>\n</li><li><strong>Crypto-Stack-Kopplung:</strong> <code>CryptoServiceKey</code> (<code>ckn</code>, <code>sak</code>) erfordert eine lückenlose Abbildung auf den AUTOSAR Crypto Stack (<code>Csm</code> / <code>CryIf</code> / <code>Crypto</code>). Vor allem der Master Key (CAK/CKN) muss in einem Secure Hardware Extension (SHE) oder Hardware Security Module (HSM) gegen Auslesen geschützt hinterlegt sein.\n</li><li><strong>Replay Protection Tuning:</strong> In deterministischen Automotive-Backbones (z. B. TSN/AVB) muss <code>replayProtectionWindow</code> so gewählt werden, dass Out-of-Order-Pakete (z. B. durch parallele Switch-Queues) nicht fälschlich verworfen werden, Replay-Angriffe jedoch strikt blockiert bleiben.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ac4a098169fae3b3", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Metamodell-Ausschnitt / Klassendiagramm aus dem AUTOSAR System Template (<code>AUTOSAR_TPS_SystemTemplate</code>, Release R22-11).\n</li><li><strong>Architektur-Kontext:</strong> Definiert das formale System-Description-Metamodell zur Abbildung von Layer-2-Sicherheit nach <strong>IEEE 802.1AE (MACsec)</strong> und <strong>IEEE 802.1X (MKA – MACsec Key Agreement Protocol)</strong> für Ethernet-Netzwerktopologien.\n</li><li><strong>Funktionaler Zweck:</strong> Modellierung der statischen Bindeglieder zwischen physischen/logischen Ethernet-Ports (<code>CouplingPort</code>, <code>EthernetCommunicationController</code>), den MKA-Teilnehmerrollen (<code>MacSecKayParticipant</code>), Kryptoschlüsseln (<code>CryptoServiceKey</code>) sowie Security-Parametern (Cipher-Suites, Replay-Schutz, Vertraulichkeits-Offsets). Dient als Eingangsbeschreibung zur Codegenerierung für die AUTOSAR-BSW (u. a. <code>Eth</code>, <code>EthSwt</code>, <code>EthIf</code>, <code>MacSec</code> bzw. MKA-Daemon sowie den AUTOSAR <code>Crypto Stack</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Vererbungshierarchien &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><code>CouplingElement</code> → spezialisiert <code>FibexElement</code>\n</li><li><code>EthernetCommunicationController</code> → spezialisiert <code>CommunicationController</code>\n</li><li><code>CouplingPort</code>, <code>MacSecKayParticipant</code> → spezialisieren <code>Identifiable</code>\n</li><li><code>MacSecGlobalKayProps</code>, <code>MacSecParticipantSet</code>, <code>CryptoServiceKey</code> → spezialisieren <code>ARElement</code> und tragen den Stereotyp <code>«UploadableDesignElement»</code>\n</li><li><code>EthernetCluster</code> → spezialisiert <code>CommunicationCluster</code>\n</li></ul>\n<h5 class=\"fig-section-h5\">Topologie- &amp; Port-Entitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>CouplingElement</code>:</strong> Repräsentiert Layer-2-Koppelelemente (z. B. Ethernet-Switches) mit <code>couplingType: CouplingElementEnum [0..1]</code>. Komponiert <code>couplingPort [0..*]</code> über die Komposition <code>«atpVariation, atpSplitable»</code>.\n</li><li><strong><code>EthernetCommunicationController</code>:</strong> ECU-Ethernet-Controller mit Parametern für MAC-Unicast-Adresse, Puffergrenzen und Slave-Verhalten; referenziert <code>couplingPort [0..*]</code>.\n</li><li><strong><code>CouplingPort</code>:</strong> Physischer oder logischer Switch-/Controller-Port. Definiert Verhandlungsverhalten, Port-Rollen und Layer-Typen (<code>connectionNegotiationBehavior</code>, <code>couplingPortRole</code>, <code>macLayerType</code>, <code>physicalLayerType</code>, <code>receiveActivity</code>). Komponiert <code>macSecProps [0..*]</code>.\n</li><li><strong><code>EthernetCluster</code>:</strong> Kommunikationscluster für Ethernet-Netzwerke; parametriert <code>couplingPortStartupActiveTime</code> und <code>couplingPortSwitchoffDelay</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">MACsec- &amp; MKA-Konfigurationsentitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>MacSecProps</code>:</strong> Laufzeit- und Betriebsmodi des MACsec-Layers auf Port-Ebene:\n<ul class=\"fig-list\"><li><code>autoStart: Boolean [0..1]</code>: Automatisches Aktivieren der MACsec-Verarbeitung nach Link-Up.\n</li><li><code>onFailPermissiveMode: MacSecFailPermissiveModeEnum [0..1]</code> (<code>never</code>, <code>timeout</code>): Verhalten bei MKA-Verhandlungsfehlschlag (Plaintext-Fallback).\n</li><li><code>onFailPermissiveModeTimeout: TimeValue [0..1]</code>: Gültigkeitsdauer des Permissive-Modes.\n</li><li><code>sakRekeyTimeSpan: TimeValue [0..1]</code>: Intervall für periodisches Rekeying des Security Association Key (SAK).\n</li><li>Komposition <code>macSecKayConfig [0..1]</code> → <code>MacSecLocalKayProps</code>.\n</li></ul>\n</li><li><strong><code>MacSecLocalKayProps</code>:</strong> Lokale MKA/KAY-Eigenschaften der Schnittstelle:\n<ul class=\"fig-list\"><li><code>role: MacSecRoleEnum [0..1]</code> (<code>peer</code>, <code>keyServer</code>): Lokale MKA-Rolle.\n</li><li><code>keyServerPriority: PositiveInteger [0..1]</code>: Priorität bei der dynamischen Key-Server-Wahl.\n</li><li><code>sourceMacAddress</code>, <code>destinationMacAddress</code>: L2-Adressierung der MKA-Nachbarn.\n</li><li>Referenziert <code>globalKayProps [0..1]</code> → <code>MacSecGlobalKayProps</code>.\n</li><li>Referenziert <code>mkaParticipant [0..*]</code> → <code>MacSecKayParticipant</code>.\n</li></ul>\n</li><li><strong><code>MacSecGlobalKayProps</code>:</strong> Globale Whitelist- und Bypass-Regeln (<code>«UploadableDesignElement»</code>):\n<ul class=\"fig-list\"><li><code>bypassEtherType: PositiveInteger [0..255]</code>: EtherTypes, die unverschlüsselt/unauthentifiziert passieren.\n</li><li><code>bypassVlan: PositiveInteger [0..255]</code>: VLANs für Bypass.\n</li></ul>\n</li><li><strong><code>MacSecParticipantSet</code>:</strong> Aggregation von MKA-Teilnehmern (<code>«UploadableDesignElement»</code>); referenziert optional <code>ethernetCluster [0..1]</code> → <code>EthernetCluster</code> und komponiert <code>mkaParticipant [0..*]</code> → <code>MacSecKayParticipant</code>.\n</li><li><strong><code>MacSecKayParticipant</code>:</strong> Modelliert einen MKA-Teilnehmer (<code>Identifiable</code>). Referenziert über Assoziationen <code>ckn [0..1]</code> und <code>sak [0..1]</code> Instanzen von <code>CryptoServiceKey</code> und komponiert <code>cryptoAlgoConfig [0..1]</code> → <code>MacSecCryptoAlgoConfig</code>.\n</li><li><strong><code>CryptoServiceKey</code>:</strong> Kryptografischer Schlüssel (<code>«UploadableDesignElement»</code>) mit optionalen Attributen <code>algorithmFamily: String [0..1]</code>, <code>keyGeneration: CryptoServiceKeyGenerationEnum [0..1]</code>, <code>keyStorageType: String [0..1]</code> und <code>length: PositiveInteger [0..1]</code>.\n</li><li><strong><code>MacSecCryptoAlgoConfig</code>:</strong> Krypto-Algorithmus- und Sicherheitsparameter:\n<ul class=\"fig-list\"><li><code>capability: MacSecCapabilityEnum [0..1]</code> (<code>intergrityWithoutConfidentiality</code>, <code>intergrityAndConfidentiality</code>).\n</li><li><code>confidentialityOffset: MacSecConfidentialityOffsetEnum [0..1]</code> (<code>ConfidentialityOffset_0</code>, <code>ConfidentialityOffset_30</code>, <code>ConfidentialityOffset_50</code>).\n</li><li><code>replayProtection: Boolean [0..1]</code>, <code>replayProtectionWindow: PositiveInteger [0..1]</code>.\n</li><li>Komponiert <code>cipherSuiteConfig [0..4]</code> → <code>MacSecCipherSuiteConfig</code> mit <code>cipherSuite: String [0..1]</code> und <code>cipherSuitePriority: PositiveInteger [0..1]</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Aus den Parametern leitet sich folgende protokollarische Zustands- und Ablaufkette ab:</p>\n<ol class=\"fig-list\"><li><strong>Initialisierung &amp; Link-Up:</strong>\n<ul class=\"fig-list\"><li>Detektiert der Ethernet-Treiber den Link-Up und ist <code>autoStart == true</code>, wird der MKA-Protokollstack (Control Plane) auf dem jeweiligen <code>CouplingPort</code> getriggert.\n</li></ul>\n</li><li><strong>Peer Discovery &amp; Key-Server-Wahl:</strong>\n<ul class=\"fig-list\"><li>MKA sendet EAPOL-MKA-PDUs an <code>destinationMacAddress</code>.\n</li><li>Bei Peer-to-Peer-Beziehungen werten die Teilnehmer <code>keyServerPriority</code> und MAC-Adressen aus; der Teilnehmer mit dem kleinsten Prioritätswert (höchste Präferenz) wird zum <code>keyServer</code>.\n</li></ul>\n</li><li><strong>Authentifizierung &amp; Key Distribution:</strong>\n<ul class=\"fig-list\"><li>Die Authentifizierung erfolgt über den vorab konfigurierten <code>ckn</code> (Connectivity Association Key Name).\n</li><li>Der Key-Server erzeugt den Security Association Key (<code>sak</code>) und verteilt diesen verschlüsselt an die Teilnehmer.\n</li></ul>\n</li><li><strong>Data Plane Enforcement (SecY-Konfiguration):</strong>\n<ul class=\"fig-list\"><li>Der abgeleitete SAK wird in die MACsec-Hardware-Engine (SecY) geladen.\n</li><li>Die Hardware wendet <code>capability</code> (nur ICV-Authentifizierung oder Authentifizierung + Verschlüsselung) sowie <code>replayProtectionWindow</code> an.\n</li><li>Bei Paketen mit passendem <code>bypassEtherType</code> oder <code>bypassVlan</code> wird der SecY-Kryptopfad umgangen.\n</li></ul>\n</li><li><strong>Rekeying &amp; Fehlerabfall:</strong>\n<ul class=\"fig-list\"><li>Vor Ablauf von <code>sakRekeyTimeSpan</code> rolliert der Key-Server automatisch einen neuen SAK ein (Zero-Packet-Loss Rekeying).\n</li><li>Schlägt die MKA-Aushandlung fehl oder bricht der Session-Status ab:\n<ul class=\"fig-list\"><li><code>onFailPermissiveMode == never</code>: Der Port verwirft sofort allen nicht-konformen Plaintext-Verkehr (Fail-Secure).\n</li><li><code>onFailPermissiveMode == timeout</code>: Unverschlüsselter Datenverkehr wird für die Dauer von <code>onFailPermissiveModeTimeout</code> temporär toleriert, bevor der Datenpfad geschlossen wird.\n</li></ul>\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Hardware-Offloading (SecY):</strong> MACsec IEEE 802.1AE erfordert Line-Rate-Kryptografie. Die Konfigurationen aus <code>MacSecCryptoAlgoConfig</code> zielen direkt auf integrierte Hardware-Crypto-Engines in Switch-ICs oder Ethernet-MACs ab. Fehlt dem Controller die HW-Unterstützung, droht immenser MCU-Overhead oder Frame-Dropping.\n</li><li><strong>Header-Transparenz via <code>confidentialityOffset</code>:</strong>\n<ul class=\"fig-list\"><li><code>ConfidentialityOffset_0</code>: Verschlüsselung ab Beginn der Nutzlast (hinter SecTAG).\n</li><li><code>ConfidentialityOffset_30</code> / <code>ConfidentialityOffset_50</code>: Erlaubt das Belassen unverschlüsselter L3/L4-Header (IPv4 bzw. IPv6 / TCP/UDP). Dies ist zwingend erforderlich, wenn Zwischenknoten (z. B. Switched Gateways) Paketinspektion, Routing oder QoS-Klassifizierung ohne vollständige MACsec-Terminierung durchführen müssen.\n</li></ul>\n</li><li><strong>Crypto-Stack-Kopplung:</strong> <code>CryptoServiceKey</code> (<code>ckn</code>, <code>sak</code>) erfordert eine lückenlose Abbildung auf den AUTOSAR Crypto Stack (<code>Csm</code> / <code>CryIf</code> / <code>Crypto</code>). Vor allem der Master Key (CAK/CKN) muss in einem Secure Hardware Extension (SHE) oder Hardware Security Module (HSM) gegen Auslesen geschützt hinterlegt sein.\n</li><li><strong>Replay Protection Tuning:</strong> In deterministischen Automotive-Backbones (z. B. TSN/AVB) muss <code>replayProtectionWindow</code> so gewählt werden, dass Out-of-Order-Pakete (z. B. durch parallele Switch-Queues) nicht fälschlich verworfen werden, Replay-Angriffe jedoch strikt blockiert bleiben.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-1fc1650078b96d42", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Metamodell-Ausschnitt / Klassendiagramm aus dem AUTOSAR System Template (<code>AUTOSAR_TPS_SystemTemplate</code>, Release R22-11).\n</li><li><strong>Architektur-Kontext:</strong> Definiert das formale System-Description-Metamodell zur Abbildung von Layer-2-Sicherheit nach <strong>IEEE 802.1AE (MACsec)</strong> und <strong>IEEE 802.1X (MKA – MACsec Key Agreement Protocol)</strong> für Ethernet-Netzwerktopologien.\n</li><li><strong>Funktionaler Zweck:</strong> Modellierung der statischen Bindeglieder zwischen physischen/logischen Ethernet-Ports (<code>CouplingPort</code>, <code>EthernetCommunicationController</code>), den MKA-Teilnehmerrollen (<code>MacSecKayParticipant</code>), Kryptoschlüsseln (<code>CryptoServiceKey</code>) sowie Security-Parametern (Cipher-Suites, Replay-Schutz, Vertraulichkeits-Offsets). Dient als Eingangsbeschreibung zur Codegenerierung für die AUTOSAR-BSW (u. a. <code>Eth</code>, <code>EthSwt</code>, <code>EthIf</code>, <code>MacSec</code> bzw. MKA-Daemon sowie den AUTOSAR <code>Crypto Stack</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Vererbungshierarchien &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><code>CouplingElement</code> → spezialisiert <code>FibexElement</code>\n</li><li><code>EthernetCommunicationController</code> → spezialisiert <code>CommunicationController</code>\n</li><li><code>CouplingPort</code>, <code>MacSecKayParticipant</code> → spezialisieren <code>Identifiable</code>\n</li><li><code>MacSecGlobalKayProps</code>, <code>MacSecParticipantSet</code>, <code>CryptoServiceKey</code> → spezialisieren <code>ARElement</code> und tragen den Stereotyp <code>«UploadableDesignElement»</code>\n</li><li><code>EthernetCluster</code> → spezialisiert <code>CommunicationCluster</code>\n</li></ul>\n<h5 class=\"fig-section-h5\">Topologie- &amp; Port-Entitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>CouplingElement</code>:</strong> Repräsentiert Layer-2-Koppelelemente (z. B. Ethernet-Switches) mit <code>couplingType: CouplingElementEnum [0..1]</code> und <code>switchMacAddressLearningMode: SwitchMacAddressLearningEnum [0..1]</code>. Komponiert <code>couplingPort [0..*]</code> über die Komposition <code>«atpVariation, atpSplitable»</code>.\n</li><li><strong><code>EthernetCommunicationController</code>:</strong> ECU-Ethernet-Controller mit Parametern für MAC-Unicast-Adresse, Puffergrenzen und Slave-Verhalten; referenziert <code>couplingPort [0..*]</code>.\n</li><li><strong><code>CouplingPort</code>:</strong> Physischer oder logischer Switch-/Controller-Port. Definiert Verhandlungsverhalten, Port-Rollen und Layer-Typen (<code>connectionNegotiationBehavior</code>, <code>couplingPortRole</code>, <code>macLayerType</code>, <code>physicalLayerType</code>, <code>receiveActivity</code>). Komponiert <code>macSecProps [0..*]</code>.\n</li><li><strong><code>EthernetCluster</code>:</strong> Kommunikationscluster für Ethernet-Netzwerke; parametriert <code>couplingPortStartupActiveTime</code> und <code>couplingPortSwitchoffDelay</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">MACsec- &amp; MKA-Konfigurationsentitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>MacSecProps</code>:</strong> Laufzeit- und Betriebsmodi des MACsec-Layers auf Port-Ebene:\n<ul class=\"fig-list\"><li><code>autoStart: Boolean [0..1]</code>: Automatisches Aktivieren der MACsec-Verarbeitung nach Link-Up.\n</li><li><code>onFailPermissiveMode: MacSecFailPermissiveModeEnum [0..1]</code> (<code>never</code>, <code>timeout</code>): Verhalten bei MKA-Verhandlungsfehlschlag (Plaintext-Fallback).\n</li><li><code>onFailPermissiveModeTimeout: TimeValue [0..1]</code>: Gültigkeitsdauer des Permissive-Modes.\n</li><li><code>sakRekeyTimeSpan: TimeValue [0..1]</code>: Intervall für periodisches Rekeying des Security Association Key (SAK).\n</li><li>Komposition <code>macSecKayConfig [0..1]</code> → <code>MacSecLocalKayProps</code>.\n</li></ul>\n</li><li><strong><code>MacSecLocalKayProps</code>:</strong> Lokale MKA/KAY-Eigenschaften der Schnittstelle:\n<ul class=\"fig-list\"><li><code>role: MacSecRoleEnum [0..1]</code> (<code>peer</code>, <code>keyServer</code>): Lokale MKA-Rolle.\n</li><li><code>keyServerPriority: PositiveInteger [0..1]</code>: Priorität bei der dynamischen Key-Server-Wahl.\n</li><li><code>sourceMacAddress</code>, <code>destinationMacAddress</code>: L2-Adressierung der MKA-Nachbarn.\n</li><li>Referenziert <code>globalKayProps [0..1]</code> → <code>MacSecGlobalKayProps</code>.\n</li><li>Referenziert <code>mkaParticipant [0..*]</code> → <code>MacSecKayParticipant</code>.\n</li></ul>\n</li><li><strong><code>MacSecGlobalKayProps</code>:</strong> Globale Whitelist- und Bypass-Regeln (<code>«UploadableDesignElement»</code>):\n<ul class=\"fig-list\"><li><code>bypassEtherType: PositiveInteger [0..255]</code>: EtherTypes, die unverschlüsselt/unauthentifiziert passieren.\n</li><li><code>bypassVlan: PositiveInteger [0..255]</code>: VLANs für Bypass.\n</li></ul>\n</li><li><strong><code>MacSecParticipantSet</code>:</strong> Aggregation von MKA-Teilnehmern (<code>«UploadableDesignElement»</code>); referenziert optional <code>ethernetCluster [0..1]</code> → <code>EthernetCluster</code> und komponiert <code>mkaParticipant [0..*]</code> → <code>MacSecKayParticipant</code>.\n</li><li><strong><code>MacSecKayParticipant</code>:</strong> Modelliert einen MKA-Teilnehmer (<code>Identifiable</code>). Referenziert über Assoziationen <code>ckn [0..1]</code> und <code>sak [0..1]</code> Instanzen von <code>CryptoServiceKey</code> und komponiert <code>cryptoAlgoConfig [0..1]</code> → <code>MacSecCryptoAlgoConfig</code>.\n</li><li><strong><code>CryptoServiceKey</code>:</strong> Kryptografischer Schlüssel (<code>«UploadableDesignElement»</code>) mit optionalen Attributen <code>algorithmFamily: String [0..1]</code>, <code>keyGeneration: CryptoServiceKeyGenerationEnum [0..1]</code>, <code>keyStorageType: String [0..1]</code> und <code>length: PositiveInteger [0..1]</code>.\n</li><li><strong><code>MacSecCryptoAlgoConfig</code>:</strong> Krypto-Algorithmus- und Sicherheitsparameter:\n<ul class=\"fig-list\"><li><code>capability: MacSecCapabilityEnum [0..1]</code> (<code>intergrityWithoutConfidentiality</code>, <code>intergrityAndConfidentiality</code>).\n</li><li><code>confidentialityOffset: MacSecConfidentialityOffsetEnum [0..1]</code> (<code>ConfidentialityOffset_0</code>, <code>ConfidentialityOffset_30</code>, <code>ConfidentialityOffset_50</code>).\n</li><li><code>replayProtection: Boolean [0..1]</code>, <code>replayProtectionWindow: PositiveInteger [0..1]</code>.\n</li><li>Komponiert <code>cipherSuiteConfig [0..4]</code> → <code>MacSecCipherSuiteConfig</code> mit <code>cipherSuite: String [0..1]</code> und <code>cipherSuitePriority: PositiveInteger [0..1]</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Aus den Parametern leitet sich folgende protokollarische Zustands- und Ablaufkette ab:</p>\n<ol class=\"fig-list\"><li><strong>Initialisierung &amp; Link-Up:</strong>\n<ul class=\"fig-list\"><li>Detektiert der Ethernet-Treiber den Link-Up und ist <code>autoStart == true</code>, wird der MKA-Protokollstack (Control Plane) auf dem jeweiligen <code>CouplingPort</code> getriggert.\n</li></ul>\n</li><li><strong>Peer Discovery &amp; Key-Server-Wahl:</strong>\n<ul class=\"fig-list\"><li>MKA sendet EAPOL-MKA-PDUs an <code>destinationMacAddress</code>.\n</li><li>Bei Peer-to-Peer-Beziehungen werten die Teilnehmer <code>keyServerPriority</code> und MAC-Adressen aus; der Teilnehmer mit dem kleinsten Prioritätswert (höchste Präferenz) wird zum <code>keyServer</code>.\n</li></ul>\n</li><li><strong>Authentifizierung &amp; Key Distribution:</strong>\n<ul class=\"fig-list\"><li>Die Authentifizierung erfolgt über den vorab konfigurierten <code>ckn</code> (Connectivity Association Key Name).\n</li><li>Der Key-Server erzeugt den Security Association Key (<code>sak</code>) und verteilt diesen verschlüsselt an die Teilnehmer.\n</li></ul>\n</li><li><strong>Data Plane Enforcement (SecY-Konfiguration):</strong>\n<ul class=\"fig-list\"><li>Der abgeleitete SAK wird in die MACsec-Hardware-Engine (SecY) geladen.\n</li><li>Die Hardware wendet <code>capability</code> (nur ICV-Authentifizierung oder Authentifizierung + Verschlüsselung) sowie <code>replayProtectionWindow</code> an.\n</li><li>Bei Paketen mit passendem <code>bypassEtherType</code> oder <code>bypassVlan</code> wird der SecY-Kryptopfad umgangen.\n</li></ul>\n</li><li><strong>Rekeying &amp; Fehlerabfall:</strong>\n<ul class=\"fig-list\"><li>Vor Ablauf von <code>sakRekeyTimeSpan</code> rolliert der Key-Server automatisch einen neuen SAK ein (Zero-Packet-Loss Rekeying).\n</li><li>Schlägt die MKA-Aushandlung fehl oder bricht der Session-Status ab:\n<ul class=\"fig-list\"><li><code>onFailPermissiveMode == never</code>: Der Port verwirft sofort allen nicht-konformen Plaintext-Verkehr (Fail-Secure).\n</li><li><code>onFailPermissiveMode == timeout</code>: Unverschlüsselter Datenverkehr wird für die Dauer von <code>onFailPermissiveModeTimeout</code> temporär toleriert, bevor der Datenpfad geschlossen wird.\n</li></ul>\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Hardware-Offloading (SecY):</strong> MACsec IEEE 802.1AE erfordert Line-Rate-Kryptografie. Die Konfigurationen aus <code>MacSecCryptoAlgoConfig</code> zielen direkt auf integrierte Hardware-Crypto-Engines in Switch-ICs oder Ethernet-MACs ab. Fehlt dem Controller die HW-Unterstützung, droht immenser MCU-Overhead oder Frame-Dropping.\n</li><li><strong>Header-Transparenz via <code>confidentialityOffset</code>:</strong>\n<ul class=\"fig-list\"><li><code>ConfidentialityOffset_0</code>: Verschlüsselung ab Beginn der Nutzlast (hinter SecTAG).\n</li><li><code>ConfidentialityOffset_30</code> / <code>ConfidentialityOffset_50</code>: Erlaubt das Belassen unverschlüsselter L3/L4-Header (IPv4 bzw. IPv6 / TCP/UDP). Dies ist zwingend erforderlich, wenn Zwischenknoten (z. B. Switched Gateways) Paketinspektion, Routing oder QoS-Klassifizierung ohne vollständige MACsec-Terminierung durchführen müssen.\n</li></ul>\n</li><li><strong>Crypto-Stack-Kopplung:</strong> <code>CryptoServiceKey</code> (<code>ckn</code>, <code>sak</code>) erfordert eine lückenlose Abbildung auf den AUTOSAR Crypto Stack (<code>Csm</code> / <code>CryIf</code> / <code>Crypto</code>). Vor allem der Master Key (CAK/CKN) muss in einem Secure Hardware Extension (SHE) oder Hardware Security Module (HSM) gegen Auslesen geschützt hinterlegt sein.\n</li><li><strong>Replay Protection Tuning:</strong> In deterministischen Automotive-Backbones (z. B. TSN/AVB) muss <code>replayProtectionWindow</code> so gewählt werden, dass Out-of-Order-Pakete (z. B. durch parallele Switch-Queues) nicht fälschlich verworfen werden, Replay-Angriffe jedoch strikt blockiert bleiben.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-94871872392512ad", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Metamodell-Ausschnitt / Klassendiagramm aus dem AUTOSAR System Template (<code>AUTOSAR_TPS_SystemTemplate</code>, Release R22-11).\n</li><li><strong>Architektur-Kontext:</strong> Definiert das formale System-Description-Metamodell zur Abbildung von Layer-2-Sicherheit nach <strong>IEEE 802.1AE (MACsec)</strong> und <strong>IEEE 802.1X (MKA – MACsec Key Agreement Protocol)</strong> für Ethernet-Netzwerktopologien.\n</li><li><strong>Funktionaler Zweck:</strong> Modellierung der statischen Bindeglieder zwischen physischen/logischen Ethernet-Ports (<code>CouplingPort</code>, <code>EthernetCommunicationController</code>), den MKA-Teilnehmerrollen (<code>MacSecKayParticipant</code>), Kryptoschlüsseln (<code>CryptoServiceKey</code>) sowie Security-Parametern (Cipher-Suites, Replay-Schutz, Vertraulichkeits-Offsets). Dient als Eingangsbeschreibung zur Codegenerierung für die AUTOSAR-BSW (u. a. <code>Eth</code>, <code>EthSwt</code>, <code>EthIf</code>, <code>MacSec</code> bzw. MKA-Daemon sowie den AUTOSAR <code>Crypto Stack</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Vererbungshierarchien &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><code>CouplingElement</code> → spezialisiert <code>FibexElement</code>\n</li><li><code>EthernetCommunicationController</code> → spezialisiert <code>CommunicationController</code>\n</li><li><code>CouplingPort</code>, <code>MacSecKayParticipant</code> → spezialisieren <code>Identifiable</code>\n</li><li><code>MacSecGlobalKayProps</code>, <code>MacSecParticipantSet</code>, <code>CryptoServiceKey</code> → spezialisieren <code>ARElement</code> und tragen den Stereotyp <code>«UploadableDesignElement»</code>\n</li><li><code>EthernetCluster</code> → spezialisiert <code>CommunicationCluster</code>\n</li></ul>\n<h5 class=\"fig-section-h5\">Topologie- &amp; Port-Entitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>CouplingElement</code>:</strong> Repräsentiert Layer-2-Koppelelemente (z. B. Ethernet-Switches) mit <code>couplingType: CouplingElementEnum [0..1]</code> und <code>switchMacAddressLearningMode: SwitchMacAddressLearningEnum [0..1]</code>. Komponiert <code>couplingPort [0..*]</code> über die Komposition <code>«atpVariation, atpSplitable»</code>.\n</li><li><strong><code>EthernetCommunicationController</code>:</strong> ECU-Ethernet-Controller mit Parametern für MAC-Unicast-Adresse, Puffergrenzen und Slave-Verhalten; referenziert <code>couplingPort [0..*]</code>.\n</li><li><strong><code>CouplingPort</code>:</strong> Physischer oder logischer Switch-/Controller-Port. Definiert Verhandlungsverhalten, Port-Rollen und Layer-Typen (<code>connectionNegotiationBehavior</code>, <code>couplingPortRole</code>, <code>macLayerType</code>, <code>physicalLayerType</code>, <code>receiveActivity</code>). Komponiert <code>macSecProps [0..*]</code>.\n</li><li><strong><code>EthernetCluster</code>:</strong> Kommunikationscluster für Ethernet-Netzwerke; parametriert <code>couplingPortStartupActiveTime</code> und <code>couplingPortSwitchoffDelay</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">MACsec- &amp; MKA-Konfigurationsentitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>MacSecProps</code>:</strong> Laufzeit- und Betriebsmodi des MACsec-Layers auf Port-Ebene:\n<ul class=\"fig-list\"><li><code>autoStart: Boolean [0..1]</code>: Automatisches Aktivieren der MACsec-Verarbeitung nach Link-Up.\n</li><li><code>onFailPermissiveMode: MacSecFailPermissiveModeEnum [0..1]</code> (<code>never</code>, <code>timeout</code>): Verhalten bei MKA-Verhandlungsfehlschlag (Plaintext-Fallback).\n</li><li><code>onFailPermissiveModeTimeout: TimeValue [0..1]</code>: Gültigkeitsdauer des Permissive-Modes.\n</li><li><code>sakRekeyTimeSpan: TimeValue [0..1]</code>: Intervall für periodisches Rekeying des Security Association Key (SAK).\n</li><li>Komposition <code>macSecKayConfig [0..1]</code> → <code>MacSecLocalKayProps</code>.\n</li></ul>\n</li><li><strong><code>MacSecLocalKayProps</code>:</strong> Lokale MKA/KAY-Eigenschaften der Schnittstelle:\n<ul class=\"fig-list\"><li><code>role: MacSecRoleEnum [0..1]</code> (<code>peer</code>, <code>keyServer</code>): Lokale MKA-Rolle.\n</li><li><code>keyServerPriority: PositiveInteger [0..1]</code>: Priorität bei der dynamischen Key-Server-Wahl.\n</li><li><code>sourceMacAddress</code>, <code>destinationMacAddress</code>: L2-Adressierung der MKA-Nachbarn.\n</li><li>Referenziert <code>globalKayProps [0..1]</code> → <code>MacSecGlobalKayProps</code>.\n</li><li>Referenziert <code>mkaParticipant [0..*]</code> → <code>MacSecKayParticipant</code>.\n</li></ul>\n</li><li><strong><code>MacSecGlobalKayProps</code>:</strong> Globale Whitelist- und Bypass-Regeln (<code>«UploadableDesignElement»</code>):\n<ul class=\"fig-list\"><li><code>bypassEtherType: PositiveInteger [0..255]</code>: EtherTypes, die unverschlüsselt/unauthentifiziert passieren.\n</li><li><code>bypassVlan: PositiveInteger [0..255]</code>: VLANs für Bypass.\n</li></ul>\n</li><li><strong><code>MacSecParticipantSet</code>:</strong> Aggregation von MKA-Teilnehmern (<code>«UploadableDesignElement»</code>); referenziert optional <code>ethernetCluster [0..1]</code> → <code>EthernetCluster</code> und komponiert <code>mkaParticipant [0..*]</code> → <code>MacSecKayParticipant</code>.\n</li><li><strong><code>MacSecKayParticipant</code>:</strong> Modelliert einen MKA-Teilnehmer (<code>Identifiable</code>) mit dem Attribut <code>connectivityKeyName: PositiveUnlimitedInteger [0..1]</code>. Referenziert über die Assoziation <code>cak [0..1]</code> eine Instanz von <code>CryptoServiceKey</code> und komponiert <code>cryptoAlgoConfig [0..1]</code> → <code>MacSecCryptoAlgoConfig</code>.\n</li><li><strong><code>CryptoServiceKey</code>:</strong> Kryptografischer Schlüssel (<code>«UploadableDesignElement»</code>) mit optionalen Attributen <code>algorithmFamily: String [0..1]</code>, <code>keyGeneration: CryptoServiceKeyGenerationEnum [0..1]</code>, <code>keyStorageType: String [0..1]</code> und <code>length: PositiveInteger [0..1]</code>.\n</li><li><strong><code>MacSecCryptoAlgoConfig</code>:</strong> Krypto-Algorithmus- und Sicherheitsparameter:\n<ul class=\"fig-list\"><li><code>capability: MacSecCapabilityEnum [0..1]</code> (<code>intergrityWithoutConfidentiality</code>, <code>intergrityAndConfidentiality</code>).\n</li><li><code>confidentialityOffset: MacSecConfidentialityOffsetEnum [0..1]</code> (<code>ConfidentialityOffset_0</code>, <code>ConfidentialityOffset_30</code>, <code>ConfidentialityOffset_50</code>).\n</li><li><code>replayProtection: Boolean [0..1]</code>, <code>replayProtectionWindow: PositiveInteger [0..1]</code>.\n</li><li>Komponiert <code>cipherSuiteConfig [0..4]</code> → <code>MacSecCipherSuiteConfig</code> mit <code>cipherSuite: String [0..1]</code> und <code>cipherSuitePriority: PositiveInteger [0..1]</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Statische Systemkonfiguration:</strong> Das Klassendiagramm beschreibt eine rein deklarative Metamodellstruktur zur Konfiguration von MACsec/MKA; es enthält keine dynamischen Interaktions- oder Verhaltenssequenzen.\n</li><li><strong>Laufzeit-Initialisierung &amp; Key Agreement (MKA):</strong>\n<ol class=\"fig-list\"><li>Link-Up an einem <code>CouplingPort</code> triggert bei gesetztem <code>autoStart == true</code> die Initialisierung der MACsec-Verarbeitung.\n</li><li><code>MacSecLocalKayProps</code> initialisiert den MKA-Teilnehmer (<code>MacSecKayParticipant</code>) mit den über <code>CryptoServiceKey</code> (<code>cak</code>) und <code>connectivityKeyName</code> bereitgestellten Schlüsseln/Credentials und den konfigurierten Rollen (<code>role</code>, <code>keyServerPriority</code>).\n</li><li>Bei erfolgreicher MKA-Aushandlung wird der Sitzungsschlüssel (SAK) dynamisch generiert/verteilt und nach Ablauf von <code>sakRekeyTimeSpan</code> erneuert.\n</li><li>Schlägt die MKA-Aushandlung fehl, greift abhängig von <code>onFailPermissiveMode</code> der Fallback (<code>never</code> oder temporär bis <code>onFailPermissiveModeTimeout</code>).\n</li><li>Für den Datenpfad determinieren <code>MacSecCryptoAlgoConfig</code> und <code>MacSecCipherSuiteConfig</code> Authentifizierungs-, Verschlüsselungs- und Replay-Window-Prüfungen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Hardware-Offloading (SecY):</strong> MACsec IEEE 802.1AE erfordert Line-Rate-Kryptografie. Die Konfigurationen aus <code>MacSecCryptoAlgoConfig</code> zielen direkt auf integrierte Hardware-Crypto-Engines in Switch-ICs oder Ethernet-MACs ab. Fehlt dem Controller die HW-Unterstützung, droht immenser MCU-Overhead oder Frame-Dropping.\n</li><li><strong>Header-Transparenz via <code>confidentialityOffset</code>:</strong>\n<ul class=\"fig-list\"><li><code>ConfidentialityOffset_0</code>: Verschlüsselung ab Beginn der Nutzlast (hinter SecTAG).\n</li><li><code>ConfidentialityOffset_30</code> / <code>ConfidentialityOffset_50</code>: Erlaubt das Belassen unverschlüsselter L3/L4-Header (IPv4 bzw. IPv6 / TCP/UDP). Dies ist zwingend erforderlich, wenn Zwischenknoten (z. B. Switched Gateways) Paketinspektion, Routing oder QoS-Klassifizierung ohne vollständige MACsec-Terminierung durchführen müssen.\n</li></ul>\n</li><li><strong>Crypto-Stack-Kopplung:</strong> <code>CryptoServiceKey</code> (<code>ckn</code>, <code>sak</code>) erfordert eine lückenlose Abbildung auf den AUTOSAR Crypto Stack (<code>Csm</code> / <code>CryIf</code> / <code>Crypto</code>). Vor allem der Master Key (CAK/CKN) muss in einem Secure Hardware Extension (SHE) oder Hardware Security Module (HSM) gegen Auslesen geschützt hinterlegt sein.\n</li><li><strong>Replay Protection Tuning:</strong> In deterministischen Automotive-Backbones (z. B. TSN/AVB) muss <code>replayProtectionWindow</code> so gewählt werden, dass Out-of-Order-Pakete (z. B. durch parallele Switch-Queues) nicht fälschlich verworfen werden, Replay-Angriffe jedoch strikt blockiert bleiben.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-0927f41a7157ca0e", "to": "FIG-ac4a098169fae3b3", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>CouplingElement</code>: Attribut <code>couplingType</code> erhält Kardinalität <code>[0..1]</code>.\n</li><li><code>CryptoServiceKey</code>: Stereotyp <code>«UploadableDesignElement»</code> ergänzt; Attribute <code>algorithmFamily</code> und <code>length</code> erhalten Kardinalität <code>[0..1]</code>.\n</li><li><code>MacSecGlobalKayProps</code>: Stereotyp <code>«UploadableDesignElement»</code> ergänzt.\n</li><li><code>MacSecParticipantSet</code>: Stereotyp <code>«UploadableDesignElement»</code> ergänzt.\n</li></ul>"}, {"from": "FIG-ac4a098169fae3b3", "to": "FIG-1fc1650078b96d42", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>CouplingElement</code>: Attribut <code>switchMacAddressLearningMode: SwitchMacAddressLearningEnum [0..1]</code> ergänzt.\n</li><li><code>MacSecConfidentialityOffsetEnum</code>: Kopfzeile <code>literals</code> im Enumeration-Körper ergänzt.\n</li><li><code>MacSecCapabilityEnum</code>: Kopfzeile <code>literals</code> im Enumeration-Körper ergänzt.\n</li><li><code>MacSecRoleEnum</code>: Kopfzeile <code>literals</code> im Enumeration-Körper ergänzt; abgeschnittener Stereotyp-Header <code>«enumerati...</code> zu <code>«enumeration»</code> korrigiert.\n</li><li><code>MacSecFailPermissiveModeEnum</code>: Kopfzeile <code>literals</code> im Enumeration-Körper ergänzt.\n</li></ul>"}, {"from": "FIG-1fc1650078b96d42", "to": "FIG-94871872392512ad", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>MacSecKayParticipant</code>: Attribut <code>connectivityKeyName: PositiveUnlimitedInteger [0..1]</code> ergänzt.\n</li><li><code>MacSecKayParticipant</code>: Assoziationsende <code>+sak</code> zu <code>CryptoServiceKey</code> entfernt.\n</li><li><code>MacSecKayParticipant</code>: Assoziationsende <code>+ckn</code> zu <code>CryptoServiceKey</code> umbenannt in <code>+cak</code>.\n</li></ul>"}]};
